Build a particle morph hero for {{CLIENT_NAME}}.

6000 THREE.js BufferGeometry points morphing between brand keywords:
- Words to morph: [{{CLIENT_NAME}}, '{{CLIENT_PRODUCT}}', ...add 2 more brand keywords...]
- Sampling function:
```javascript
function sampleWord(word,count){
  const cv=document.createElement('canvas');cv.width=600;cv.height=200;
  const ctx=cv.getContext('2d');ctx.fillStyle='#fff';
  ctx.font='bold 160px Arial';ctx.textAlign='center';ctx.textBaseline='middle';
  ctx.fillText(word,300,100);
  const data=ctx.getImageData(0,0,600,200).data;
  const pixels=[];for(let i=0;i<data.length;i+=4)if(data[i+3]>128){const x=(i/4)%600,y=Math.floor((i/4)/600);pixels.push([(x/600-.5)*8,-(y/200-.5)*2.5,0]);}
  const step=Math.max(1,Math.floor(pixels.length/count));const s=[];for(let i=0;i<pixels.length&&s.length<count;i+=step)s.push(pixels[i]);while(s.length<count)s.push([...s[Math.floor(Math.random()*s.length)]]);return s;
}
```
